<?php
 namespace Pterodactyl\Services\Dezerx\Minecraft; use Illuminate\Support\Facades\Cache; use Illuminate\Support\Facades\Http; class VersionCatalog { private const BASE = 'https://mcjars.app/api/v2'; private const TTL = [1800, 21600]; private const TIMEOUT = 12; private const MAX_BUILDS = 100; private const GROUPS = [ 'recommended' => 'Recommended', 'established' => 'Established', 'experimental' => 'Experimental', 'miscellaneous' => 'Miscellaneous', 'limbos' => 'Limbo servers', ]; public static function platforms(): array { return Cache::flexible('mcjars:types', self::TTL, function () { $groups = self::get('/types')['types'] ?? []; $platforms = []; foreach (self::GROUPS as $group => $groupLabel) { foreach ($groups[$group] ?? [] as $type => $meta) { $platforms[strtolower((string) $type)] = [ 'type' => (string) $type, 'label' => (string) ($meta['name'] ?? $type), 'icon' => (string) ($meta['icon'] ?? ''), 'color' => (string) ($meta['color'] ?? ''), 'description' => (string) ($meta['description'] ?? ''), 'group' => $group, 'groupLabel' => $groupLabel, 'experimental' => (bool) ($meta['experimental'] ?? false), 'deprecated' => (bool) ($meta['deprecated'] ?? false), 'builds' => (int) ($meta['builds'] ?? 0), 'versionCount' => ((int) ($meta['versions']['minecraft'] ?? 0)) ?: (int) ($meta['versions']['project'] ?? 0), ]; } } return $platforms; }); } public static function supports(string $platform): bool { return array_key_exists($platform, self::platforms()); } public static function versions(string $platform): array { $type = self::type($platform); if ($type === null) { return []; } return Cache::flexible( 'mcjars:versions:'.$type, self::TTL, function () use ($type) { $builds = self::get('/builds/'.rawurlencode($type))['builds'] ?? []; $versions = []; foreach ($builds as $id => $meta) { $versions[] = [ 'id' => (string) $id, 'label' => (string) $id, 'stable' => ($meta['type'] ?? '') === 'RELEASE' && (bool) ($meta['supported'] ?? false), 'java' => (int) ($meta['java'] ?? 0), ]; } return array_reverse($versions); }, ); } public static function builds(string $platform, string $version): array { $type = self::type($platform); if ($type === null) { return []; } return Cache::flexible( 'mcjars:builds:'.$type.':'.sha1($version), self::TTL, function () use ($type, $version) { $builds = self::get( '/builds/'.rawurlencode($type).'/'.rawurlencode($version), )['builds'] ?? []; $out = []; foreach ($builds as $build) { if (! is_array($build)) { continue; } $id = self::buildId($build); if ($id === null) { continue; } $out[] = [ 'id' => $id, 'label' => (string) ($build['name'] ?? $id), 'stable' => ! (bool) ($build['experimental'] ?? false), ]; if (count($out) >= self::MAX_BUILDS) { break; } } return $out; }, ); } public static function chosen(string $platform, string $version, ?string $build = null): array { $type = self::type($platform); $empty = ['id' => null, 'label' => null, 'java' => 0, 'installation' => []]; if ($type === null) { return $empty; } return Cache::flexible( 'mcjars:install:'.$type.':'.sha1($version.'|'.($build ?? '')), self::TTL, function () use ($type, $version, $build, $empty) { $chosen = self::resolveBuild($type, $version, $build); if ($chosen === []) { return $empty; } $steps = $chosen['installation'] ?? null; return [ 'id' => self::buildId($chosen), 'label' => ($chosen['name'] ?? null) === null ? null : (string) $chosen['name'], 'java' => self::java($type, $version), 'installation' => is_array($steps) ? $steps : [], ]; }, ); } public static function javaForVersion(string $version): int { if ($version === '') { return 0; } foreach (self::versions('vanilla') as $entry) { if (($entry['id'] ?? null) === $version) { return (int) ($entry['java'] ?? 0); } } return 0; } private static function java(string $type, string $version): int { $builds = self::get('/builds/'.rawurlencode($type))['builds'] ?? []; return (int) ($builds[$version]['java'] ?? 0); } private static function resolveBuild(string $type, string $version, ?string $build): array { if ($build === null || $build === 'latest') { $versions = self::get('/builds/'.rawurlencode($type))['builds'] ?? []; $latest = $versions[$version]['latest'] ?? null; return is_array($latest) ? $latest : []; } $builds = self::get( '/builds/'.rawurlencode($type).'/'.rawurlencode($version), )['builds'] ?? []; foreach ($builds as $entry) { if (is_array($entry) && self::buildId($entry) === $build) { return $entry; } } return []; } private static function buildId(array $build): ?string { $project = $build['projectVersionId'] ?? null; if (is_string($project) && $project !== '') { return $project; } $number = $build['buildNumber'] ?? null; if ($number !== null && (int) $number !== 0) { return (string) $number; } $uuid = $build['uuid'] ?? null; return is_string($uuid) && $uuid !== '' ? $uuid : null; } private static function type(string $platform): ?string { $type = self::platforms()[$platform]['type'] ?? null; return is_string($type) ? $type : null; } private static function get(string $path): array { $response = Http::timeout(self::TIMEOUT) ->connectTimeout(5) ->acceptJson() ->get(self::BASE.$path); if ($response->failed()) { return []; } $payload = $response->json(); return is_array($payload) ? $payload : []; } } 